var n=[{title:`Wat het bewijs laat zien`,text:`De American Academy of Pediatrics beschouwt goed opgezette krachttraining voor jongeren als nuttig, met een laag blessurepercentage bij goede instructie en toezicht. Er is niet aangetoond dat krachttraining onder goed toezicht de lengtegroei remt of groeischijven beschadigt alleen doordat er gewichten worden gebruikt.`},{title:`Begin met de bewegingsbasis`,text:`Squats met lichaamsgewicht, push-upvarianten, rows, spring- en landingsoefeningen en oefeningen met lichte weerstand leren je controle. Oefen symmetrische bewegingen en bewegingen op één been, leer hoe je met de uitrusting omgaat en maak het zwaarder op basis van je techniek en rijpheid, niet op wat je vrienden tillen.`},{title:`Het totale beeld van activiteit`,text:`De richtlijn van de CDC voor 6–17 jaar raadt elke dag minstens 60 minuten matige tot intensieve lichamelijke activiteit aan, inclusief spier- en botversterkende activiteit op minstens drie dagen per week. Krachttrainingen zijn daar een deel van, naast sport, spel en recreatie.`},{title:`Waarom toezicht ertoe doet`,text:`Gekwalificeerde coaching, uitrusting die bij je leeftijd past, genoeg rust en een veilige ruimte verminderen vermijdbare risico’s. Vermijd pogingen met maximaal gewicht zonder toezicht, en forceer je opbouw niet en begin niet zelf aan gevorderd tillen. Betrek waar mogelijk een ouder, voogd of gekwalificeerde coach. Heb je pijn, een belangrijke medische aandoening of zorgen over je ontwikkeling, vraag het dan aan een arts. Geen enkel trainingsplan kan groei, blessurepreventie of prestatieresultaten garanderen.`}];var t=[{label:`American Academy of Pediatrics: krachttraining voor jongeren`,url:`https://publications.aap.org/pediatrics/article/145/6/e20201010/76942/`},{label:`CDC: lichaamsbeweging voor kinderen en tieners`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/children.html`}];var a={sections:n,sources:t};export{a as default,n as sections,t as sources};